const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let session=null,local={local:[],catalog:[],selected:null},lab={jobs:[],plans:[],releases:[]},notice='',carousel=0;
let timer=null;
const head=(label,title,desc)=>`<div class="page-head"><div><div class="eyebrow">${label}</div><h1>${title}</h1><p class="head-description">${desc}</p></div><button class="button secondary" id="learning-refresh">Refresh local workspace</button></div>`;
const number=n=>typeof n==='number'?n.toFixed(4):'—';
const modelOptions=()=>local.local.map(m=>`<option value="${m.id}" ${m.id===local.selected?'selected':''}>${esc(m.name)} · ${m.engine}</option>`).join('');
function setup(){return session?'':`<section class="card" style="margin-bottom:24px"><h2>Start the local workspace</h2><p class="muted">Training and model weights live on your computer. Open the app from the local service to use these controls.</p><pre style="white-space:pre-wrap">python local-learning/service.py</pre><p class="small muted">Then open http://127.0.0.1:8765. The dependency-free trainer is ready with Python. Install local-learning/requirements.txt for TRIDENT and approved Hugging Face publishing.</p><p class="notice">${esc(notice||'This page has not connected to a local training service. No job has been started.')}</p></section>`;}
function trainingFields(prefix='train'){return `<div class="form-grid"><div class="field wide"><label for="${prefix}-name">Model or experiment name</label><input id="${prefix}-name" maxlength="80" value="My Synthia experiment"></div><div class="field"><label for="${prefix}-engine">Training engine</label><select id="${prefix}-engine"><option value="byte-ngram">Local byte n-gram · no dependencies</option><option value="trident" ${session&&!session.torch?'disabled':''}>SynthAI2 TRIDENT · requires PyTorch</option></select></div><div class="field"><label for="${prefix}-head">Specialist head</label><select id="${prefix}-head"><option value="research">Research</option><option value="code">Code</option><option value="math">Math</option></select></div><div class="field"><label for="${prefix}-epochs">TRIDENT epochs</label><input id="${prefix}-epochs" type="number" min="1" max="10" value="2"></div><div class="field"><label for="${prefix}-order">Baseline order</label><select id="${prefix}-order"><option>1</option><option selected>2</option><option>3</option></select></div><div class="field wide"><label for="${prefix}-text">Approved training material</label><textarea id="${prefix}-text" rows="7" placeholder="Paste material you want this local model to learn. 200–200,000 UTF-8 bytes."></textarea><p class="small muted">Only this material is used. Chart details and reflection notes are never imported automatically.</p></div></div>`;}
function jobRows(){return lab.jobs.slice().reverse().map(j=>`<article class="note"><div class="row spread"><h3 style="margin:0">${esc(j.name)}</h3><span class="pill">${esc(j.status)}</span></div><p class="small muted">${j.engine} · ${j.head} · ${j.engine==='byte-ngram'?`order ${j.order}`:`${j.epochs} epochs`}</p>${j.progress?.fraction!=null?`<progress max="1" value="${j.progress.fraction}" style="width:100%" aria-label="Training progress"></progress>`:''}<div class="row"><span class="small">Training loss ${number(j.progress?.training_loss)}</span><span class="small">Held-out loss ${number(j.progress?.evaluation_loss)}</span></div>${j.error?`<p class="error">${esc(j.error)}</p>`:''}${j.status==='running'?`<button class="button secondary" data-cancel-job="${j.id}" style="margin-top:12px">Cancel run</button>`:''}</article>`).join('')||'<div class="empty">No training runs yet. Start one with your own material.</div>';}
export function trainingView(){return head('LOCAL TRAINING','A small model, made here.','Train on your material, retain checkpoints, and inspect held-out results.')+setup()+`<div class="notes-grid"><section class="card"><h2>Prepare a training run</h2>${trainingFields()}<p class="notice">Baseline training counts byte transitions in one pass. TRIDENT trains the selected specialist head from scratch on CPU. Both are experimental.</p><label class="row" style="font-weight:400"><input type="checkbox" id="train-approved"> I approve this local training run on the material above.</label><button class="button" id="start-training" ${session?'':'disabled'}>Start local training</button><div id="learning-message" class="error" role="status"></div></section><section><div class="card-title"><h2>Run history</h2><span class="pill">Local checkpoints</span></div><div id="learning-jobs">${jobRows()}</div></section></div>`;}
export function shopView(){return head('MODEL GO ROUND SHOPPE','Find the right model for the job.','Browse SynthAI2’s specialist roles and test models you have trained locally.')+setup()+`<section class="card"><div class="card-title"><h2>Your local shelf</h2><span class="pill">${local.local.length} trained models</span></div>${local.local.length?`<div class="three-grid">${local.local.map(m=>`<article class="note"><div class="eyebrow">${esc(m.engine)}</div><h2>${esc(m.name)}</h2><p class="muted small">${esc(m.quality)}<br>Head: ${m.head} · ${m.engine==='byte-ngram'?`order ${m.order}`:`${m.epochs} epochs`}</p><p class="small">Held-out loss: ${number(m.metrics.evaluation_loss)}</p><button class="button ${m.id===local.selected?'lime':'secondary'}" data-select-model="${m.id}">${m.id===local.selected?'Selected for test bench':'Select for test bench'}</button></article>`).join('')}</div>`:'<p class="muted">Train a model to add its checkpoint and evaluation card to this shelf.</p>'}</section><div class="bottom-grid"><section class="card"><div class="card-title"><h2>Specialist carousel</h2><div class="row"><button class="button secondary" id="carousel-prev" aria-label="Previous model">Previous</button><button class="button secondary" id="carousel-next" aria-label="Next model">Next</button></div></div><div id="carousel-card">${catalogCard()}</div></section><section class="card"><h2>Local test bench</h2><p class="muted small">Generate a short completion from a local checkpoint. This does not replace Synthia’s source-based assistant.</p><div class="field"><label for="test-model">Model</label><select id="test-model">${modelOptions()||'<option>No local model yet</option>'}</select></div><div class="field" style="margin-top:15px"><label for="test-prompt">Test prompt</label><textarea id="test-prompt" rows="3" placeholder="Research observes…"></textarea></div><button class="button" id="test-generation" style="margin-top:15px" ${local.local.length?'':'disabled'}>Test local model</button><div id="model-output" class="text-block" style="margin-top:18px" role="status"></div></section></div>`;}
function catalogCard(){if(!local.catalog.length)return '<p class="muted">Connect the local service to load SynthAI2’s seven-model registry.</p>';const m=local.catalog[((carousel%local.catalog.length)+local.catalog.length)%local.catalog.length];return `<div class="eyebrow">${carousel%local.catalog.length+1} / ${local.catalog.length} · ${esc(m.execution_scope)}</div><h2>${esc(m.id)}</h2><p>${esc(m.job)}</p><div class="notice"><b>Input:</b> ${esc(m.input_contract)}<br><b>Output:</b> ${esc(m.output_contract)}<br><b>Status:</b> Reference only; not installed or verified.</div><p class="small muted">Fallback: ${esc(m.fallback||'None specified')}</p><a class="button secondary" href="https://huggingface.co/${esc(m.repo)}" target="_blank" rel="noopener noreferrer">Inspect model on Hugging Face</a>`;}
export function labView(){return head('AUTO LAB','Experiment. Compare. Learn.','Approve a bounded plan, then let the local service run the trials.')+setup()+`<div class="notes-grid"><section class="card"><h2>An approved experiment plan</h2>${trainingFields('lab')}<div class="form-grid"><div class="field"><label for="lab-runs">Number of runs</label><input id="lab-runs" type="number" min="1" max="5" value="3"></div><div class="field"><label for="lab-interval">Interval in minutes</label><input id="lab-interval" type="number" min="1" max="1440" value="1"></div></div><p class="notice">One run at a time, up to five trials. Baseline trials compare orders 1, 2, and 3. TRIDENT trials increase epochs from your starting value, capped at 10. Plans pause after a service restart.</p><label class="row" style="font-weight:400"><input type="checkbox" id="lab-approved"> I approve this bounded local experiment plan.</label><button class="button" id="start-lab" ${session?'':'disabled'}>Start Auto Lab</button><div id="learning-message" class="error" role="status"></div></section><section><div class="card-title"><h2>Experiment plans</h2><span class="pill">No automatic publishing</span></div><div id="learning-plans">${planRows()}</div><h2>Comparison table</h2><div class="card table-wrap" id="lab-comparison">${comparison()}</div><div id="learning-jobs" style="margin-top:20px">${jobRows()}</div></section></div>`;}
function planRows(){return lab.plans.map(p=>`<article class="note"><div class="row spread"><b>${esc(p.name)}</b><span class="pill">${esc(p.status)}</span></div><p class="small muted">${p.started} / ${p.runs} runs started · ${p.engine}</p>${p.error?`<p class="error">${esc(p.error)}</p>`:''}${p.status==='active'?`<button class="button secondary" data-pause-plan="${p.id}">Pause future runs</button>`:''}</article>`).join('')||'<div class="empty">No experiment plans yet.</div>';}
function comparison(){return `<table><thead><tr><th>RUN</th><th>CONFIGURATION</th><th>TRAIN LOSS</th><th>HELD-OUT LOSS</th></tr></thead><tbody>${local.local.map(m=>`<tr><td>${esc(m.name)}</td><td>${m.engine==='byte-ngram'?`order ${m.order}`:`${m.epochs} epochs`}</td><td>${number(m.metrics.training_loss)}</td><td>${number(m.metrics.evaluation_loss)}</td></tr>`).join('')||'<tr><td colspan="4">Completed runs will appear here.</td></tr>'}</tbody></table><p class="small muted">Compare only runs with the same corpus and tokenizer. Loss does not establish factual accuracy or conversational quality.</p>`;}
export function studioView(){return head('PUBLISHING STUDIO','Give good experiments a home.','Prepare a model card, evaluation report, and release bundle for review.')+setup()+`<div class="notes-grid"><section class="card"><h2>Prepare a release</h2><div class="field"><label for="release-model">Local checkpoint</label><select id="release-model">${modelOptions()||'<option>No local models yet</option>'}</select></div><div class="field" style="margin-top:15px"><label for="release-target">Destination</label><select id="release-target"><option value="github">GitHub · reviewed release</option><option value="github-pages">GitHub Release + project page</option><option value="download">Download a reviewed bundle</option><option value="huggingface">Hugging Face · new private model repo</option></select></div><div class="field" style="margin-top:15px"><label for="release-repo">Repository for publishing</label><input id="release-repo" placeholder="owner/model or owner/repository"></div><p class="notice">Bundles include the checkpoint, its model card, and evaluation metrics. Training text, charts, reflections, and credentials are excluded. Weights can still memorize training material.</p><button class="button" id="stage-release" ${local.local.length?'':'disabled'}>Prepare for review</button><div id="learning-message" class="error" role="status"></div></section><section><h2>Release review queue</h2><div id="release-queue">${releaseRows()}</div></section></div>`;}
function releaseRows(){return lab.releases.slice().reverse().map(r=>`<article class="note"><div class="row spread"><b>${esc(r.name||local.local.find(m=>m.id===r.model)?.name||'Release')}</b><span class="pill">${esc(r.status)}</span></div><p class="small muted">${esc(r.target)} ${r.repo?'· '+esc(r.repo):''} · ${(r.bytes/1024).toFixed(1)} KB</p><label class="small">Exact bundle SHA-256</label><code style="overflow-wrap:anywhere;font-size:.8rem">${r.sha256}</code><details><summary>Inspect card and included files</summary><pre style="white-space:pre-wrap">${esc(r.report||'')}\n${esc((r.included_files||[]).join('\n'))}</pre></details>${r.status==='prepared'?`<p class="notice">${r.target==='github-pages'?'Publishes a release and replaces this repository’s current GitHub Pages site.':r.target==='github'?'GitHub release visibility follows the repository visibility.':r.target==='huggingface'?'Creates a new private Hugging Face repository.':'Prepares a downloadable local artifact.'} Review the training source for sensitive material before approving.</p><label class="row" style="font-weight:400"><input type="checkbox" data-release-consent="${r.id}"> I approve this exact bundle and destination.</label><button class="button" data-approve-release="${r.id}">${r.target==='download'?'Approve bundle download':'Approve & publish'}</button>`:''}${r.status==='approved'||r.status==='published'?`<div class="row" style="margin-top:15px"><a class="button secondary" href="/api/local/releases/${r.id}/download">Download bundle</a>${r.url?`<a class="button secondary" href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">Open published release</a>`:''}</div>`:''}${r.error?`<p class="error">${esc(r.error)}</p>`:''}</article>`).join('')||'<div class="empty">Nothing is published automatically. Prepare a checkpoint for review.</div>';}
async function request(path,payload){const response=await fetch('/api/local/'+path,{method:payload?'POST':'GET',headers:payload?{'Content-Type':'application/json','X-Local-Approval':session?.token||''}:{},body:payload?JSON.stringify(payload):undefined,signal:AbortSignal.timeout(30000)});if(!response.headers.get('content-type')?.includes('application/json'))throw Error('Start the local Synthia service to use training, experiments and publishing.');const content=await response.json();if(!response.ok)throw Error(content.error||'Local service request failed.');return content;}
async function refresh(){try{session=await request('status');[local,lab]=await Promise.all([request('models'),request('lab')]);notice='';return true;}catch(error){session=null;notice=error.message;return false;}}
function values(prefix){const val=id=>document.querySelector('#'+prefix+'-'+id)?.value;return {name:val('name'),engine:val('engine'),head:val('head'),epochs:Number(val('epochs')),order:Number(val('order')),text:val('text'),approved:document.querySelector('#'+prefix+'-approved')?.checked===true};}
function message(text){const el=document.querySelector('#learning-message');if(el)el.textContent=text;}
export function cleanupLearning(){if(timer)clearInterval(timer);timer=null;}
export function bindLearning(render){cleanupLearning();if(!document.querySelector('#learning-refresh'))return;document.querySelector('#learning-refresh').onclick=async()=>{await refresh();render();};const perform=(id,fn)=>{const button=document.querySelector('#'+id);if(button)button.onclick=async()=>{button.disabled=true;try{await fn();await refresh();render();}catch(error){message(error.message);button.disabled=false;}};};perform('start-training',()=>request('train',values('train')));perform('start-lab',()=>request('plans',{...values('lab'),runs:Number(document.querySelector('#lab-runs').value),interval_seconds:Number(document.querySelector('#lab-interval').value)*60}));perform('stage-release',()=>request('releases',{model:document.querySelector('#release-model').value,target:document.querySelector('#release-target').value,repo:document.querySelector('#release-repo').value.trim()}));document.querySelectorAll('[data-select-model]').forEach(el=>el.onclick=async()=>{try{await request(`models/${el.dataset.selectModel}/select`,{});await refresh();render();}catch(error){el.textContent=error.message;}});document.querySelectorAll('[data-cancel-job]').forEach(el=>el.onclick=async()=>{await request(`jobs/${el.dataset.cancelJob}/cancel`,{});await refresh();render();});document.querySelectorAll('[data-pause-plan]').forEach(el=>el.onclick=async()=>{await request(`plans/${el.dataset.pausePlan}/pause`,{});await refresh();render();});document.querySelectorAll('[data-approve-release]').forEach(el=>el.onclick=async()=>{const id=el.dataset.approveRelease;const consent=document.querySelector(`[data-release-consent="${id}"]`);if(!consent.checked){message('Approve the exact bundle and destination first.');return;}const release=lab.releases.find(r=>r.id===id);el.disabled=true;try{await request(`releases/${id}/approve`,{approved:true,sha256:release.sha256});await refresh();render();}catch(error){message(error.message);el.disabled=false;}});const rotate=delta=>{carousel=(carousel+delta+(local.catalog.length||1))%(local.catalog.length||1);document.querySelector('#carousel-card').innerHTML=catalogCard();};document.querySelector('#carousel-prev')?.addEventListener('click',()=>rotate(-1));document.querySelector('#carousel-next')?.addEventListener('click',()=>rotate(1));document.querySelector('#test-generation')?.addEventListener('click',async()=>{const out=document.querySelector('#model-output');out.textContent='Generating locally…';try{const result=await request(`models/${document.querySelector('#test-model').value}/generate`,{prompt:document.querySelector('#test-prompt').value,max_new:80});out.textContent=`${result.text||'(No completion found for this prompt.)'}\n\n${result.quality}`;}catch(error){out.textContent=error.message;}});if(session)timer=setInterval(async()=>{await refresh();const jobs=document.querySelector('#learning-jobs');if(jobs){jobs.innerHTML=jobRows();jobs.querySelectorAll('[data-cancel-job]').forEach(el=>el.onclick=async()=>{await request(`jobs/${el.dataset.cancelJob}/cancel`,{});await refresh();render();});}const plans=document.querySelector('#learning-plans');if(plans){plans.innerHTML=planRows();plans.querySelectorAll('[data-pause-plan]').forEach(el=>el.onclick=async()=>{try{await request(`plans/${el.dataset.pausePlan}/pause`,{});await refresh();render();}catch(error){message(error.message);}});}const comparisonEl=document.querySelector('#lab-comparison');if(comparisonEl)comparisonEl.innerHTML=comparison();},3000);}
